    private Entity $entity;

    /**
     * @throws IdentifierException
     */
    public function __construct(
        HaContext $ha,
        public EntityId $id,
    ) {
        if (!self::isGeneratedEntityId($id)) {
            throw IdentifierException::entityNotGenerated($id->value, self::getDomain());
        }

        $this->entity = $ha->getEntity($id);
    }

    public static function getDomain(): string
    {
        return 'sensor';
    }

    public static function isGeneratedEntityId(EntityId $id): bool
    {
        return isset(self::GENERATED_ENTITY_IDS[$id->value]);
    }

    public function getState(): ?SensorState
    {
        return SensorState::fromNullableState($this->entity->getState());
    }

    /**
     * @throws StateException
     */
    public function requireState(): SensorState
    {
        return new SensorState($this->entity->requireState());
    }

    public function watchStateChanges(): StateChangeStream
    {
        return $this->entity->watchStateChanges();
    }

    /**
     * @throws HistoryException
     */
    public function getHistory(HistoryQuery $query): EntityStateHistory
    {
        return $this->entity->getHistory($query);
    }

    /**
     * @return array<string, mixed>
     */
    public function listAttributes(): array
    {
        $state = $this->entity->getState();

        return $state === null ? [] : $state->attributes;
    }

    public function getEntity(): Entity
    {
        return $this->entity;
    }

    public function toServiceTarget(): ServiceTarget
    {
        return $this->entity->toServiceTarget();
    }
}
